def word_frequency(text: str) -> dict[str, int]:
    import string
    counts = {}
    for word in text.lower().split():
        clean_word = word.strip(string.punctuation)
        if clean_word:
            counts[clean_word] = counts.get(clean_word, 0) + 1
    return counts
